"use client";

/**
 * Underwater Dashboard
 *
 * A real HTML sales dashboard (live revenue counter, area chart, streaming orders, a working search box)
 * lying on the floor of a tiled pool. Chrome's HTML-in-Canvas API draws the live DOM into a WebGL texture
 * every frame; a ripple simulation on top refracts it, throws caustics across it and catches glints of
 * light. The pointer drags a wake through the water, a click splashes, and the dashboard keeps updating
 * underneath: new orders slide in, the total ticks up, typing in the search box filters the list.
 *
 * Usage
 *   <div style={{ position: "relative", height: 560 }}>
 *     <UnderwaterDashboard
 *       brand="Saltline"
 *       orders={[{ city: "Lisbon", item: "Linen tote · 2 items", amount: 248, color: "#ff4b36" }]}
 *     />
 *   </div>
 *
 * Theming
 *   Follows your shadcn theme out of the box: a light dashboard in a bright, sunlit pool by default, a navy
 *   dashboard in a deep night pool under a `.dark` ancestor. The water, the pool rim, the badge and the
 *   tiles' grout read the Tailwind v4 variables --color-background, --color-foreground,
 *   --color-muted-foreground and --color-border; the shader takes its colours from those CSS variables
 *   and re-reads them when the theme changes. Pass theme="light" or theme="dark" to fix it, `accent` for
 *   the dashboard's brand colour.
 *
 * Browser support
 *   The water effect needs Chrome 157+ (the HTML-in-Canvas API, `texElementSubImage2D`). Safari, Firefox
 *   and older Chrome get the same live dashboard as plain HTML on a still pool, with a small pill saying so.
 *
 * Fills its parent (width and height 100%) and scales the dashboard to fit. Idle autoplay plays a scripted
 * pass (a wake, a search for the next city, an order landing, a shower of drops) and loops; it stops when a
 * visitor moves the pointer and comes back after 6 s. Pauses off screen and in hidden tabs;
 * prefers-reduced-motion gets one still frame. No dependencies besides React.
 */

import * as React from "react";

export interface UnderwaterOrder {
  /** City shown as the order's title; the search box matches it. */
  city: string;
  /** Line under the city, such as "Linen tote · 2 items". */
  item: string;
  /** Order total. */
  amount: number;
  /** Colour of the round initials tile. */
  color?: string;
  /** Age label, such as "2s". "now" shows "just now". */
  ago?: string;
}

export interface UnderwaterKpi {
  /** Small caps label, such as "Visitors now". */
  label: string;
  /** The figure. A plain whole number (like "3,482") on the first card ticks live. */
  value: string;
  /** Change line, such as "▲ 12%". */
  delta: string;
  /** Shows the change in the accent colour (a bad move) instead of green. */
  down?: boolean;
}

export interface UnderwaterDashboardProps {
  /** "auto" follows the `.dark` class like shadcn; "light" or "dark" fixes both the pool and the dashboard. */
  theme?: "auto" | "light" | "dark";
  /** The dashboard's brand colour: chart, highlights, new-order flash. */
  accent?: string;
  /** Strength of the ripples and the ambient swell (0 = still water, 2 = choppy). */
  waves?: number;
  /** Plays the scripted pass when nobody is interacting. */
  autoplay?: boolean;
  /** Shows the small "This dashboard is real HTML" pill. */
  badge?: boolean;
  /** Bold part of the badge. */
  badgeLabel?: string;
  /** Second part of the badge (hidden on narrow sizes). */
  badgeDetail?: string;
  /** Pill shown instead of the badge in browsers without HTML-in-Canvas. */
  fallbackLabel?: string;
  /** Shop name in the dashboard's top bar. */
  brand?: string;
  /** Initials in the avatar. */
  initials?: string;
  /** Tabs in the top bar; the first starts selected and a click on the water over a tab selects it. */
  tabs?: string[];
  /** Placeholder of the search box. */
  searchPlaceholder?: string;
  /** Label above the big revenue counter. */
  revenueLabel?: string;
  /** Revenue the counter starts from. */
  revenue?: number;
  /** Green growth pill next to the order count. */
  growth?: string;
  /** Grey comparison text after the pills. */
  compareText?: string;
  /** Orders count the pill starts from; it ticks up as orders arrive. */
  orderCount?: number;
  /** Labels on the chart's two grid lines, top first. */
  chartLabels?: [string, string];
  /** Title of the orders column. */
  ordersTitle?: string;
  /** Orders in the live list, newest first. */
  orders?: UnderwaterOrder[];
  /** Orders that arrive while it plays. Defaults to four built-in ones (or `orders` when you pass your own). */
  incoming?: UnderwaterOrder[];
  /** The four cards under the chart. */
  kpis?: UnderwaterKpi[];
  /** Accessible name of the whole piece. */
  label?: string;
  /** Class on the root element. */
  className?: string;
  /** Style on the root element (it fills its parent by default). */
  style?: React.CSSProperties;
}

const ORDERS: UnderwaterOrder[] = [
  { city: "Lisbon", item: "Linen tote · 2 items", amount: 248, color: "#ff4b36", ago: "2s" },
  { city: "Kyoto", item: "Ceramic set · 3 items", amount: 412.5, color: "#1f8fff", ago: "9s" },
  { city: "Austin", item: "Field jacket", amount: 189, color: "#0f9f6e", ago: "14s" },
  { city: "Oslo", item: "Wool throw · 2 items", amount: 326, color: "#7a4dff", ago: "21s" },
  { city: "Cape Town", item: "Desk lamp", amount: 142.9, color: "#ff9a3c", ago: "33s" },
  { city: "Melbourne", item: "Pour-over kit", amount: 96, color: "#e0407a", ago: "41s" },
  { city: "Toronto", item: "Canvas sneakers", amount: 158, color: "#14a3b8", ago: "52s" },
];
const INCOMING: UnderwaterOrder[] = [
  { city: "Kyoto", item: "Tea cabinet · 1 item", amount: 1240, color: "#1f8fff" },
  { city: "Lisbon", item: "Linen sofa cover", amount: 860, color: "#ff4b36" },
  { city: "Oslo", item: "Wool rug · 1 item", amount: 975, color: "#7a4dff" },
  { city: "Austin", item: "Leather duffel", amount: 690, color: "#0f9f6e" },
];
const KPIS: UnderwaterKpi[] = [
  { label: "Visitors now", value: "3,482", delta: "▲ 12%" },
  { label: "Conversion", value: "4.81%", delta: "▲ 0.6" },
  { label: "Avg. order", value: "$86.40", delta: "▲ 3%" },
  { label: "Refunds", value: "0.9%", delta: "▼ 0.2", down: true },
];
const TABS = ["Overview", "Orders", "Customers", "Payouts"];
const CHART_LABELS: [string, string] = ["$1.2M", "$600K"];

const P = "uwd";
const SANS = 'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';
const SERIF = '"Instrument Serif", ui-serif, Georgia, "Times New Roman", serif';
const MONO = '"JetBrains Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace';

// Stage palettes (--uwd-*). The shader reads the colour and number entries every time the theme changes.
// Values that read a shadcn token keep a fallback; a fixed theme ("light" / "dark") uses only the fallbacks,
// because the page's tokens may belong to the other mode.
type Palette = { [key: string]: string };
const LIGHT: Palette = {
  // a bright, shallow, sunlit pool: pale aqua tiles, near-white grout, soft daylight shadow
  bg: "color-mix(in oklab, #a8e2ea 86%, var(--color-background, #ffffff))",
  "tile-a": "#6cc9d8",
  "tile-b": "#86d6e2",
  grout: "color-mix(in oklab, var(--color-background, #ffffff) 72%, #d2f2f5)",
  mid: "#ffffff",
  edge: "#c4e4ec",
  haze: "#a9dde6",
  glow: "#2fb6c9",
  hazek: ".05",
  caus: ".45",
  shadow: ".5",
  base: ".99",
  sheen: ".3",
  lap: ".55",
  "tag-bg": "color-mix(in srgb, var(--color-background, #ffffff) 82%, transparent)",
  "tag-ink": "var(--color-foreground, #0b1a33)",
  "tag-sub": "var(--color-muted-foreground, #5b6676)",
  "tag-line": "color-mix(in srgb, var(--color-border, #dde3ea) 80%, transparent)",
  "tag-dot": "#10b981",
  "tag-shadow": "0 6px 20px rgba(9, 72, 86, 0.16)",
  rim: "color-mix(in srgb, var(--color-foreground, #0b1a33) 8%, transparent)",
};
const DARK: Palette = {
  // a deep pool at night: navy tiles lit from below, caustics glowing over the dashboard
  bg: "color-mix(in oklab, #06142e 88%, var(--color-background, #0a0a0a))",
  "tile-a": "#0b2c50",
  "tile-b": "#0e3660",
  grout: "color-mix(in oklab, var(--color-background, #0a0a0a) 22%, #2a6a9c)",
  mid: "#f2f8ff",
  edge: "#2c4672",
  haze: "#03102a",
  glow: "#4fd0ff",
  hazek: ".2",
  caus: "1.35",
  shadow: ".55",
  base: ".82",
  sheen: "1",
  lap: "1",
  "tag-bg": "color-mix(in srgb, var(--color-background, #0a0a0a) 72%, transparent)",
  "tag-ink": "var(--color-foreground, #f5f7fb)",
  "tag-sub": "var(--color-muted-foreground, #a1a1aa)",
  "tag-line": "color-mix(in srgb, var(--color-foreground, #ffffff) 16%, transparent)",
  "tag-dot": "#5cffa8",
  "tag-shadow": "0 6px 22px rgba(0, 0, 0, 0.45)",
  rim: "rgba(255, 255, 255, 0.06)",
};
const STAGE_COLORS = ["tile-a", "tile-b", "grout", "mid", "edge", "haze", "glow"];
const STAGE_NUMBERS = ["hazek", "caus", "shadow", "base", "sheen", "lap"];
const decl = (p: Palette, fixed: boolean) =>
  Object.keys(p)
    .map((k) => `--${P}-${k}:${fixed ? p[k].replace(/var\(--[a-z-]+, (#[0-9A-Fa-f]+)\)/g, "$1") : p[k]}`)
    .join(";");

// The dashboard's own palettes: warm paper in the light pool, navy in the dark one.
const DASH_LIGHT = "--d-bg:#fbf6ec;--d-card:#fffdf8;--d-ink:#0b1a33;--d-mute:#6b7488;--d-line:#ece4d6;--d-acc2:#ff9a3c;--d-good:#0f9f6e;--d-chip:#fff0e6";
const DASH_DARK = "--d-bg:#0a1634;--d-card:#112352;--d-ink:#f4f7ff;--d-mute:#9aa8cc;--d-line:#20356e;--d-acc2:#ffc04d;--d-good:#4ff0b0;--d-chip:#1b2f66";

const CSS = `
.${P}-root{container-type:size;${decl(LIGHT, false)}}
:where(.dark) .${P}-root,.${P}-root:where(.dark){${decl(DARK, false)}}
.${P}-root[data-uwd-theme="light"]{${decl(LIGHT, true)}}
.${P}-root[data-uwd-theme="dark"]{${decl(DARK, true)}}
.${P}-dash{--d-acc:#ff4b36;${DASH_LIGHT};
 position:absolute;left:0;top:0;width:1120px;height:604px;box-sizing:border-box;padding:22px 26px 24px;border-radius:30px;pointer-events:none;
 background:var(--d-bg);color:var(--d-ink);display:grid;grid-template-columns:1fr 392px;grid-template-rows:56px 1fr 128px;gap:18px;text-align:left;
 font-family:${SANS};font-feature-settings:"tnum" 1,"cv11" 1;line-height:normal;-webkit-font-smoothing:antialiased}
:where(.dark) .${P}-root .${P}-dash,.${P}-root:where(.dark) .${P}-dash{${DASH_DARK}}
.${P}-root[data-uwd-theme="light"] .${P}-dash{${DASH_LIGHT}}
.${P}-root[data-uwd-theme="dark"] .${P}-dash{${DASH_DARK}}
.${P}-dash *{box-sizing:border-box}
.${P}-top{grid-column:1/3;display:flex;align-items:center;gap:22px}
.${P}-logo{display:flex;align-items:center;gap:10px;font:800 21px ${SANS};letter-spacing:-.02em;white-space:nowrap}
.${P}-logo i{width:30px;height:30px;border-radius:10px;background:conic-gradient(from 200deg,var(--d-acc),var(--d-acc2),var(--d-acc));display:block}
.${P}-tabs{display:flex;gap:4px;margin-left:10px}
.${P}-tabs span{padding:9px 14px;border-radius:12px;font:600 15px ${SANS};color:var(--d-mute)}
.${P}-tabs span.${P}-on{background:var(--d-ink);color:var(--d-bg)}
.${P}-search{position:relative;margin-left:auto;width:340px;height:50px;border-radius:16px;background:var(--d-card);box-shadow:inset 0 0 0 1.5px var(--d-line);display:flex;align-items:center;gap:10px;padding:0 14px}
.${P}-search.${P}-focus{box-shadow:inset 0 0 0 2.5px var(--d-acc)}
.${P}-search svg{flex:none}
.${P}-search input{flex:1;min-width:0;border:0;outline:none;background:transparent;font:600 18px ${SANS};color:var(--d-ink);caret-color:var(--d-acc);padding:0;margin:0}
.${P}-search input::placeholder{color:var(--d-mute);font-weight:500;opacity:1}
.${P}-search kbd{font:600 12px ${MONO};color:var(--d-mute);padding:4px 7px;border-radius:7px;box-shadow:inset 0 0 0 1px var(--d-line)}
.${P}-ghost{display:none;position:absolute;left:44px;top:0;height:100%;align-items:center;font:600 18px ${SANS};color:var(--d-ink);white-space:pre;pointer-events:none}
.${P}-ghost i{display:inline-block;width:2px;height:22px;margin-left:1px;background:var(--d-acc);border-radius:1px;animation:${P}-blink 1.06s steps(1) infinite}
@keyframes ${P}-blink{50%{opacity:0}}
.${P}-search.${P}-fake .${P}-ghost{display:flex}
.${P}-search.${P}-fake input{color:transparent}
.${P}-search.${P}-fake input::placeholder{color:transparent}
.${P}-ava{width:46px;height:46px;border-radius:50%;background:linear-gradient(140deg,#2a6bff,#7a4dff);color:#fff;display:grid;place-items:center;font:700 15px ${SANS};flex:none}
.${P}-card{background:var(--d-card);border-radius:22px;box-shadow:inset 0 0 0 1.5px var(--d-line)}
.${P}-rev{padding:22px 26px 10px;display:flex;flex-direction:column;position:relative;overflow:hidden;min-width:0}
.${P}-lab{font:600 13px ${MONO};letter-spacing:.12em;text-transform:uppercase;color:var(--d-mute);display:flex;align-items:center;gap:8px;white-space:nowrap}
.${P}-lab b{width:8px;height:8px;border-radius:50%;background:var(--d-good);display:inline-block;box-shadow:0 0 0 4px color-mix(in srgb,var(--d-good) 22%,transparent)}
.${P}-big{font:800 84px/1 ${SANS};letter-spacing:-.045em;margin:12px 0 6px;white-space:nowrap}
.${P}-big small{font-size:.5em;letter-spacing:-.02em;color:var(--d-mute);font-weight:700}
.${P}-row1{display:flex;gap:10px;align-items:center;white-space:nowrap}
.${P}-pill{padding:6px 11px;border-radius:999px;font:700 14px ${SANS};background:color-mix(in srgb,var(--d-good) 14%,transparent);color:var(--d-good)}
.${P}-pill.${P}-plus{background:var(--d-acc);color:#fff;opacity:0;margin-left:auto}
.${P}-pill.${P}-o{background:var(--d-chip);color:var(--d-acc)}
.${P}-muted{color:var(--d-mute);font:500 14px ${SANS}}
.${P}-chart{margin-top:auto;display:block}
.${P}-act{grid-row:2/4;grid-column:2;padding:18px 18px 10px;display:flex;flex-direction:column;overflow:hidden}
.${P}-acth{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}
.${P}-acth h3{margin:0;font:400 30px/1 ${SERIF};letter-spacing:-.005em;color:var(--d-ink)}
.${P}-acth .${P}-muted{font:600 13px ${MONO}}
.${P}-list{display:flex;flex-direction:column}
.${P}-it{display:flex;align-items:center;gap:12px;height:62px;border-bottom:1.5px solid var(--d-line);flex:none;overflow:hidden}
.${P}-it .${P}-dot{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;font:800 15px ${SANS};color:#fff;flex:none}
.${P}-it .${P}-nm{flex:1;min-width:0}
.${P}-it .${P}-nm div{font:700 16.5px ${SANS};white-space:nowrap;letter-spacing:-.01em}
.${P}-it .${P}-nm span{font:500 13px ${SANS};color:var(--d-mute);white-space:nowrap}
.${P}-it .${P}-amt{font:800 18px ${SANS};letter-spacing:-.02em;text-align:right;white-space:nowrap}
.${P}-it .${P}-amt span{display:block;font:500 12px ${MONO};color:var(--d-mute);letter-spacing:0}
.${P}-it.${P}-dim{opacity:.3}
.${P}-it mark{background:#ffe14d;color:#0b1a33;border-radius:5px;padding:0 3px;margin:0 -3px}
.${P}-it.${P}-new{background:linear-gradient(90deg,color-mix(in srgb,var(--d-acc) 12%,transparent),transparent 80%);border-radius:14px;margin:0 -8px;padding:0 8px}
.${P}-kpis{grid-column:1;display:grid;grid-template-columns:repeat(4,1fr);gap:14px}
.${P}-kpi{padding:16px 18px;display:flex;flex-direction:column;min-width:0}
.${P}-kpi .${P}-v{font:800 31px/1 ${SANS};letter-spacing:-.035em;margin:9px 0 auto;white-space:nowrap}
.${P}-kpi .${P}-s{display:flex;align-items:flex-end;justify-content:space-between}
.${P}-kpi .${P}-d{font:700 13px ${SANS};color:var(--d-good)}
.${P}-kpi .${P}-d.${P}-n{color:var(--d-acc)}
.${P}-bars{display:flex;gap:3px;align-items:flex-end;height:26px}
.${P}-bars i{width:5px;border-radius:2px;background:var(--d-acc);opacity:.85}
.${P}-pool{position:absolute;left:0;top:0;transform-origin:0 0;overflow:hidden;
 background:radial-gradient(ellipse at 50% 45%,transparent 40%,color-mix(in srgb,var(--${P}-edge) 70%,transparent) 100%),linear-gradient(var(--${P}-grout) 2px,transparent 2px) -1px -1px/30px 30px,linear-gradient(90deg,var(--${P}-grout) 2px,transparent 2px) -1px -1px/30px 30px,linear-gradient(135deg,var(--${P}-tile-b),var(--${P}-tile-a))}
.${P}-pool .${P}-dash{box-shadow:0 22px 60px rgba(4,40,60,.35),0 2px 6px rgba(4,40,60,.2)}
.${P}-cv{position:absolute;left:0;top:0;transform-origin:0 0;display:block}
.${P}-rim{position:absolute;inset:0;pointer-events:none;z-index:1;box-shadow:inset 0 0 0 1px var(--${P}-rim)}
.${P}-cur{position:absolute;left:0;top:0;width:30px;height:30px;pointer-events:none;opacity:0;transform-origin:0 0;filter:drop-shadow(0 3px 6px rgba(0,0,0,.4));z-index:2}
.${P}-cur i{position:absolute;left:-15px;top:-15px;width:30px;height:30px;border-radius:50%;box-shadow:0 0 0 2px rgba(255,255,255,.67);opacity:0}
.${P}-cur svg{position:absolute;left:0;top:0;display:block}
.${P}-tag{position:absolute;left:50%;bottom:14px;transform:translateX(-50%);display:flex;gap:8px;align-items:center;padding:7px 12px;border-radius:999px;background:var(--${P}-tag-bg);box-shadow:inset 0 0 0 1px var(--${P}-tag-line),var(--${P}-tag-shadow);color:var(--${P}-tag-sub);font:500 12px/1.2 ${SANS};white-space:nowrap;-webkit-backdrop-filter:blur(10px) saturate(1.4);backdrop-filter:blur(10px) saturate(1.4);pointer-events:none;z-index:3;max-width:calc(100% - 24px)}
.${P}-tag b{color:var(--${P}-tag-ink);font-weight:600}
.${P}-tag i{width:7px;height:7px;border-radius:50%;background:var(--${P}-tag-dot);box-shadow:0 0 10px var(--${P}-tag-dot);flex:none}
.${P}-tag.${P}-warn i{background:#f5a524;box-shadow:0 0 10px #f5a524}
.${P}-tag span{overflow:hidden;text-overflow:ellipsis}
.${P}-probe{position:absolute;width:0;height:0;overflow:hidden;visibility:hidden;pointer-events:none}
@container (max-width:620px){.${P}-tag span{display:none}.${P}-tag{bottom:8px;font-size:11px;padding:5px 10px}}
@container (max-height:240px){.${P}-tag{display:none}}
`;

const esc = (s: string) => s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c] as string);
const money = (n: number) => n.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const fmt = (n: number) => n.toLocaleString("en-US");
const sm = (a: number, b: number, x: number) => {
  const k = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return k * k * (3 - 2 * k);
};
const lerp = (a: number, b: number, k: number) => a + (b - a) * k;
const initialsOf = (s: string) => (s.replace(/[^A-Za-z]/g, "").slice(0, 2) || "··").toUpperCase();
let seq = 0;

// ---------------- shaders ----------------
const VS = `#version 300 es
in vec2 aP; out vec2 vUv; void main(){ vUv = aP*.5+.5; gl_Position = vec4(aP,0.,1.); }`;
const DROP = `#version 300 es
precision highp float; uniform sampler2D uS; uniform vec4 uD[8]; uniform int uN; uniform float uAsp; in vec2 vUv; out vec4 o;
void main(){ vec4 c = texture(uS, vUv);
  for(int i=0;i<8;i++){ if(i>=uN) break; vec4 d = uD[i]; vec2 p = (vUv - vec2(d.x, 1.-d.y))*vec2(uAsp,1.); float r = length(p)/d.z;
    if(r<1.) c.r += d.w*(.5+.5*cos(r*3.14159265)); }
  o = c; }`;
const STEP = `#version 300 es
precision highp float; uniform sampler2D uS; uniform vec2 uTx; in vec2 vUv; out vec4 o;
void main(){ vec4 c = texture(uS, vUv);
  float a = (texture(uS, vUv+vec2(uTx.x,0.)).r + texture(uS, vUv-vec2(uTx.x,0.)).r + texture(uS, vUv+vec2(0.,uTx.y)).r + texture(uS, vUv-vec2(0.,uTx.y)).r)*.25;
  c.g += (a - c.r)*2.; c.g *= .992; c.r += c.g; c.r *= .9992; o = c; }`;
// The pool's colours come in as uniforms from the theme: tiles (uTA, uTB), grout (uGr), the light in the
// middle and at the walls (uMid, uEdge), the water's haze and caustic glow (uHaze, uGlow) and
// uK = (haze amount, caustic strength, dashboard shadow, base light) uSh, the surface sheen, and uLap, how bright ripple crests catch the light.
const FINAL = `#version 300 es
precision highp float;
uniform sampler2D uDash, uS; uniform vec2 uRes; uniform vec4 uRect; uniform float uT, uRad, uAmp; uniform vec2 uSTx, uTS;
uniform vec3 uTA, uTB, uGr, uMid, uEdge, uHaze, uGlow; uniform vec4 uK; uniform float uSh, uLap;
in vec2 vUv; out vec4 o;
float simH(vec2 uv){ return texture(uS, vec2(uv.x, 1.-uv.y)).r; }
float amb(vec2 p, float t){
  return 2.2*sin(dot(p, vec2(.0105,.0052)) - t*1.25) + 1.5*sin(dot(p, vec2(-.0062,.0118)) - t*1.02)
       + .9*sin(dot(p, vec2(.0175,-.0098)) - t*1.85) + .55*sin(dot(p, vec2(.0042,.0255)) - t*2.4)
       + .35*sin(dot(p, vec2(-.028,-.012)) - t*2.9);
}
float H(vec2 px, float t){ return simH(px/uRes)*30. + amb(px, t)*uAmp; }
float hash(vec2 p){ return fract(sin(dot(p, vec2(41.3,289.1)))*43758.55); }
float sdRR(vec2 p, vec2 b, float r){ vec2 q = abs(p)-b+r; return length(max(q,0.)) + min(max(q.x,q.y),0.) - r; }
vec3 tiles(vec2 p){
  vec2 g = p/30.; vec2 f = fract(g); vec2 id = floor(g);
  float e = min(min(f.x,1.-f.x), min(f.y,1.-f.y)); float grout = smoothstep(.025,.085,e);
  float n = hash(id);
  vec3 base = mix(uTA, uTB, n);
  base *= .96 + .06*smoothstep(.5,.1,length(f-.35));
  return mix(uGr, base, grout);
}
vec3 floorAt(vec2 p){
  vec2 c = uRect.xy + uRect.zw*.5; float d = sdRR(p - c, uRect.zw*.5, uRad);
  float ds = sdRR(p - c - vec2(8.,22.), uRect.zw*.5, uRad);
  vec3 t = tiles(p);
  float out_ = step(0.,d);
  t *= 1. - uK.z*(.5*smoothstep(26.,0.,d) + .5*smoothstep(70.,-12.,ds))*out_;
  vec4 s = texture(uDash, clamp((p - uRect.xy)/uRect.zw, 0., 1.)*uTS);
  float m = 1. - smoothstep(-.8, .8, d);
  return mix(t, s.rgb, m*s.a);
}
float caus(vec2 p, float t){
  vec2 i = p; float c = 0.;
  for(int n=0;n<4;n++){ float tt = t*(1.-3.5/float(n+1));
    i = p + vec2(cos(tt-i.x)+sin(tt+i.y), sin(tt-i.y)+cos(tt+i.x));
    c += 1./length(vec2(p.x/(sin(i.x+tt)/.006), p.y/(cos(i.y+tt)/.006))); }
  c /= 4.; c = 1.17 - pow(c, 1.4); return pow(abs(c), 7.);
}
float cn(float c){ return pow(clamp((c-.85)/1.45, 0., 1.), 3.); }
void main(){
  vec2 uv = vec2(vUv.x, 1.-vUv.y); vec2 px = uv*uRes; float t = uT;
  float e = 2.;
  float gx = (H(px+vec2(e,0.),t) - H(px-vec2(e,0.),t))/(2.*e);
  float gy = (H(px+vec2(0.,e),t) - H(px-vec2(0.,e),t))/(2.*e);
  vec2 su = uv; vec2 sx = vec2(uSTx.x,0.)*2., sy = vec2(0.,uSTx.y)*2.;
  float lap = (simH(su+sx)+simH(su-sx)+simH(su+sy)+simH(su-sy) - 4.*simH(su));
  vec2 off = -vec2(gx, gy)*58.;
  vec3 col;
  col.r = floorAt(px + off*1.00).r;
  col.g = floorAt(px + off*1.035).g;
  col.b = floorAt(px + off*1.07).b;
  vec2 cp = (px + off*2.2)/300.*6.2831 - 250.;
  float ca = cn(caus(cp, t*.55));
  float cb = cn(caus(cp*1.6 + 31., t*.42 + 4.));
  vec3 cc = vec3(cn(caus(cp + vec2(.014,0.), t*.55)), ca, cn(caus(cp - vec2(.014,0.), t*.55)));
  vec3 light = vec3(uK.w) + (cc*.55 + vec3(cb)*.12)*uK.y;
  light += clamp(-lap*300., -.1, .75)*uLap*vec3(.95,1.,1.);
  col *= light;
  float vig = length((uv-.5)*vec2(1.,.8));
  col *= mix(uMid, uEdge, smoothstep(.28,.78,vig));
  col = mix(col, uHaze, uK.x*(.3 + .7*smoothstep(.3,.8,vig)));
  col += uGlow*cc.g*.09*uK.y;
  vec2 fd = vec2(sin(px.x*.09 + px.y*.031 - t*3.3) + sin(px.y*.083 - px.x*.04 + t*2.7), cos(px.x*.071 - px.y*.06 - t*3.9) + sin(px.x*.05+px.y*.1+t*2.1))*.035*min(uAmp, 1.);
  vec3 n = normalize(vec3(-gx*2.2 + fd.x, -gy*2.2 + fd.y, 1.));
  vec3 r = reflect(vec3(0.,0.,-1.), n);
  float glint = pow(max(dot(r, normalize(vec3(.28,-.34,1.))), 0.), 1100.)*1.6;
  vec2 qb = uv + r.xy*1.6;
  float box = smoothstep(.34,.0, length((qb - vec2(.86,.06))*vec2(1.,1.7)));
  float sheen = box*box*.30 + .05*smoothstep(.95,.0,length(qb-vec2(.15,1.05)));
  col += (glint + sheen*uSh)*vec3(1.,.985,.94);
  col += .025*mix(vec3(.75,.95,1.), uGlow, .5);
  o = vec4(col, 1.);
}`;

// Design frame: a 1240×720 window with the 1120×604 dashboard centred near the top.
const DW = 1120, DH = 604, FW = 1240, FH = 720, CYCLE = 10.5;

type Tap = [number, number, number, number, number, boolean]; // x, y (virtual px), radius, strength, time, scripted
type Ptr = { x: number; y: number; on: number };
type Painter = { requestPaint?: () => void; onpaint?: (() => void) | null };

export default function UnderwaterDashboard({
  theme = "auto",
  accent = "#FF6A4D",
  waves = 1,
  autoplay = true,
  badge = true,
  badgeLabel = "This dashboard is real HTML",
  badgeDetail = "· drawn into WebGL, under a live water simulation",
  fallbackLabel = "Open in Chrome 157+ to see the WebGL effect",
  brand = "Saltline",
  initials = "AK",
  tabs = TABS,
  searchPlaceholder = "Search orders, cities…",
  revenueLabel = "Revenue today · live",
  revenue = 1284903.42,
  growth = "▲ 18.4%",
  compareText = "vs. $1.08M yesterday",
  orderCount = 14906,
  chartLabels = CHART_LABELS,
  ordersTitle = "Live orders",
  orders = ORDERS,
  incoming,
  kpis = KPIS,
  label,
  className,
  style,
}: UnderwaterDashboardProps) {
  const rootRef = React.useRef(null as HTMLDivElement | null);
  const curRef = React.useRef(null as HTMLDivElement | null);
  const dashRef = React.useRef(null as HTMLDivElement | null);
  const refreshRef = React.useRef(null as (() => void) | null);
  const [fallback, setFallback] = React.useState(false);
  const props = React.useRef({ waves, autoplay, theme });
  React.useEffect(() => {
    props.current = { waves, autoplay, theme };
  });
  const contentKey = JSON.stringify([brand, initials, tabs, searchPlaceholder, revenueLabel, revenue, growth, compareText, orderCount, chartLabels, ordersTitle, orders, incoming || null, kpis]);

  // Accent applies live to the drawn element; a theme change re-reads the stage colours.
  React.useEffect(() => {
    dashRef.current?.style.setProperty("--d-acc", accent);
  });
  React.useEffect(() => {
    refreshRef.current?.();
  }, [theme]);

  React.useEffect(() => {
    const root = rootRef.current!;
    const curEl = curRef.current!;
    const ringEl = curEl.querySelector("i") as HTMLElement;
    const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
    const uid = `${P}${++seq}`;
    const list0 = orders.length ? orders : ORDERS;
    const pool = incoming && incoming.length ? incoming : orders === ORDERS ? INCOMING : list0;
    const kp = kpis.slice(0, 4);
    const liveK = kp[0] && /^[\d,]+$/.test(kp[0].value.trim()) ? parseInt(kp[0].value.replace(/,/g, ""), 10) : -1;

    // ---------------- the real HTML dashboard ----------------
    const dash = document.createElement("div");
    dash.className = `${P}-dash`;
    dash.style.setProperty("--d-acc", accent);
    dash.innerHTML = `
<div class="${P}-top">
  <div class="${P}-logo"><i></i>${esc(brand)}</div>
  <div class="${P}-tabs">${tabs.map((t, i) => `<span${i === 0 ? ` class="${P}-on"` : ""}>${esc(t)}</span>`).join("")}</div>
  <label class="${P}-search">
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" style="color:var(--d-mute)"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.6-3.6"/></svg>
    <input type="text" placeholder="${esc(searchPlaceholder)}" autocomplete="off" spellcheck="false" aria-label="Search orders">
    <span class="${P}-ghost"><span></span><i></i></span>
    <kbd>⌘K</kbd>
  </label>
  <div class="${P}-ava">${esc(initials)}</div>
</div>
<div class="${P}-card ${P}-rev">
  <div class="${P}-lab"><b></b>${esc(revenueLabel)}</div>
  <div class="${P}-big"></div>
  <div class="${P}-row1"><span class="${P}-pill">${esc(growth)}</span><span class="${P}-pill ${P}-o"></span><span class="${P}-muted">${esc(compareText)}</span><span class="${P}-pill ${P}-plus"></span></div>
  <svg class="${P}-chart" width="652" height="196" viewBox="0 0 652 196"></svg>
</div>
<div class="${P}-card ${P}-act">
  <div class="${P}-acth"><h3>${esc(ordersTitle)}</h3><span class="${P}-muted ${P}-cnt">● streaming</span></div>
  <div class="${P}-list"></div>
</div>
<div class="${P}-kpis">${kp.map((k) => `<div class="${P}-card ${P}-kpi"><div class="${P}-lab">${esc(k.label)}</div><div class="${P}-v">${esc(k.value)}</div><div class="${P}-s"><span class="${P}-d${k.down ? ` ${P}-n` : ""}">${esc(k.delta)}</span><div class="${P}-bars"></div></div></div>`).join("")}</div>`;
    const $ = (s: string) => dash.querySelector(`.${P}-${s}`) as HTMLElement;
    const q = dash.querySelector("input") as HTMLInputElement;
    const sbox = $("search"), list = $("list"), cnt = $("cnt"), revEl = $("big"), ordEl = $("o"), plus = $("plus");
    const chart = $("chart") as unknown as SVGSVGElement;
    const ghost = dash.querySelector(`.${P}-ghost span`) as HTMLElement;
    const k1 = dash.querySelector(`.${P}-kpi .${P}-v`) as HTMLElement | null;
    const tabEls = Array.from(dash.querySelectorAll(`.${P}-tabs span`)) as HTMLElement[];
    dash.querySelectorAll(`.${P}-bars`).forEach((b, k) => {
      const sd = [7, 3, 11, 5][k % 4];
      for (let i = 0; i < 9; i++) {
        const x = document.createElement("i");
        x.style.height = 8 + ((Math.sin(i * 1.7 + sd) + 1) * 0.5) * 16 + i * 0.9 + "px";
        b.appendChild(x);
      }
    });
    const rowEl = (o: UnderwaterOrder, isNew: boolean) => {
      const d = document.createElement("div");
      d.className = `${P}-it` + (isNew ? ` ${P}-new` : "");
      d.dataset.city = o.city;
      const ago = isNew || o.ago === "now" ? "just now" : `${esc(o.ago || "1m")} ago`;
      d.innerHTML = `<div class="${P}-dot" style="background:${esc(o.color || "#1f8fff")}">${initialsOf(o.city)}</div><div class="${P}-nm"><div class="${P}-c">${esc(o.city)}</div><span>${esc(o.item)}</span></div><div class="${P}-amt">$${money(o.amount)}<span>${ago}</span></div>`;
      return d;
    };
    list0.forEach((o) => list.appendChild(rowEl(o, false)));
    let scriptFocus = false;
    const applySearch = () => {
      const s = q.value.trim().toLowerCase();
      let n = 0;
      for (const r of Array.from(list.children) as HTMLElement[]) {
        const c = r.dataset.city || "", el = r.querySelector(`.${P}-c`) as HTMLElement;
        const i = s ? c.toLowerCase().indexOf(s) : -1;
        if (s && i >= 0) {
          el.innerHTML = esc(c.slice(0, i)) + "<mark>" + esc(c.slice(i, i + s.length)) + "</mark>" + esc(c.slice(i + s.length));
          n++;
        } else el.textContent = c;
        r.classList.toggle(`${P}-dim`, !!s && i < 0);
      }
      cnt.textContent = s ? `${n} match${n === 1 ? "" : "es"}` : "● streaming";
      const real = document.activeElement === q;
      sbox.classList.toggle(`${P}-focus`, real || scriptFocus || !!s);
      sbox.classList.toggle(`${P}-fake`, scriptFocus && !real);
      ghost.textContent = q.value;
    };
    q.addEventListener("input", applySearch);
    q.addEventListener("focus", applySearch);
    q.addEventListener("blur", applySearch);
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") q.blur();
    };
    q.addEventListener("keydown", onKey);

    let newRow: HTMLElement | null = null;
    let rowT = -10, bumps = 0, addedSum = 0, lastAmt = 0;
    const addRow = (o: UnderwaterOrder, T: number) => {
      newRow?.classList.remove(`${P}-new`);
      newRow = rowEl(o, true);
      newRow.style.height = "0px";
      newRow.style.opacity = "0";
      list.prepend(newRow);
      while (list.children.length > 9) list.lastElementChild!.remove();
      rowT = T;
      bumps++;
      lastAmt = o.amount;
      addedSum += o.amount;
      plus.textContent = `+$${money(o.amount)} · ${o.city}`;
      applySearch();
    };
    const setRowK = (k: number) => {
      if (!newRow) return;
      const e = 1 - Math.pow(1 - Math.min(1, Math.max(0, k)), 3);
      newRow.style.height = 62 * e + "px";
      newRow.style.opacity = String(Math.min(1, e * 1.4));
      (newRow.firstElementChild as HTMLElement).style.transform = `translateX(${(1 - e) * -40}px) scale(${0.6 + 0.4 * e})`;
    };
    const CW = 652, CH = 196, NPT = 44;
    const base = Array.from({ length: NPT }, (_, i) => {
      const x = i / (NPT - 1);
      return 0.2 + x * 0.52 + Math.sin(i * 0.55) * 0.07 + Math.sin(i * 1.31 + 1) * 0.045;
    });
    const drawChart = (t: number, spike: number) => {
      const v = base.slice();
      v[NPT - 1] += Math.sin(t * 2.1) * 0.03 + spike * 0.16;
      v[NPT - 2] += spike * 0.05;
      const X = (i: number) => 6 + (i * (CW - 30)) / (NPT - 1), Y = (y: number) => CH - 12 - y * (CH - 40);
      let d = `M${X(0)},${Y(v[0])}`;
      for (let i = 1; i < NPT; i++) {
        const cx = (X(i - 1) + X(i)) / 2;
        d += ` C${cx},${Y(v[i - 1])} ${cx},${Y(v[i])} ${X(i)},${Y(v[i])}`;
      }
      const ex = X(NPT - 1), ey = Y(v[NPT - 1]), pul = (t * 1.3) % 1;
      chart.innerHTML = `<defs><linearGradient id="${uid}f" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--d-acc)" stop-opacity=".38"/><stop offset="1" stop-color="var(--d-acc)" stop-opacity="0"/></linearGradient>
  <linearGradient id="${uid}l" x1="0" x2="1"><stop offset="0" stop-color="var(--d-acc2)"/><stop offset="1" stop-color="var(--d-acc)"/></linearGradient></defs>
  ${[0, 1, 2, 3].map((k) => `<line x1="0" x2="${CW}" y1="${28 + k * 48}" y2="${28 + k * 48}" stroke="var(--d-line)" stroke-width="1.5" stroke-dasharray="3 6"/>`).join("")}
  <path d="${d} L${ex},${CH} L${X(0)},${CH} Z" fill="url(#${uid}f)"/><path d="${d}" fill="none" stroke="url(#${uid}l)" stroke-width="4.5" stroke-linecap="round"/>
  <circle cx="${ex}" cy="${ey}" r="${8 + pul * 16}" fill="var(--d-acc)" opacity="${0.35 * (1 - pul)}"/><circle cx="${ex}" cy="${ey}" r="7.5" fill="var(--d-card)" stroke="var(--d-acc)" stroke-width="4"/>
  <text x="${CW - 6}" y="20" text-anchor="end" font-family='${MONO}' font-weight="600" font-size="12" fill="var(--d-mute)">${esc(chartLabels[0] || "")}</text>
  <text x="${CW - 6}" y="116" text-anchor="end" font-family='${MONO}' font-weight="600" font-size="12" fill="var(--d-mute)">${esc(chartLabels[1] || "")}</text>`;
    };
    const setLive = (t: number) => {
      const k = sm(rowT + 0.1, rowT + 0.9, t);
      const r = revenue + t * 137.37 + addedSum - lastAmt + lastAmt * k;
      const w = Math.floor(r), c = Math.round((r - w) * 100) % 100;
      revEl.innerHTML = "$" + fmt(w) + "<small>." + String(c).padStart(2, "0") + "</small>";
      ordEl.textContent = fmt(orderCount + Math.floor(t * 0.9) + bumps) + " orders";
      if (k1 && liveK >= 0) k1.textContent = fmt(Math.max(0, liveK + Math.round(Math.sin(t * 0.9) * 14 + t * 2)));
      drawChart(t, bumps ? Math.sin(k * Math.PI) * 0.6 + 0.25 * (bumps > 1 ? 1 : k) : 0);
      const d = t - rowT, pk = sm(0.15, 0.4, d) * (1 - sm(4.15, 4.65, d));
      plus.style.opacity = String(pk);
      plus.style.transform = `translateY(${(1 - sm(0.15, 0.4, d)) * 10}px) scale(${0.85 + 0.15 * pk})`;
    };
    setLive(0);
    applySearch();

    // ---------------- stage: WebGL canvas with the dashboard as its drawn child, or a plain fallback ----------------
    const cv = document.createElement("canvas");
    cv.className = `${P}-cv`;
    cv.setAttribute("layoutsubtree", "");
    cv.setAttribute("content", "drawable");
    dash.setAttribute("drawable", "");
    cv.appendChild(dash);
    root.prepend(cv);
    dashRef.current = dash;
    const paint = cv as unknown as Painter;
    const gl = cv.getContext("webgl2", { antialias: false, premultipliedAlpha: false, preserveDrawingBuffer: true }) as WebGL2RenderingContext | null;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const glx = gl as any;
    let ok = !!gl && typeof glx.texElementSubImage2D === "function" && !!gl.getExtension("EXT_color_buffer_float");
    let poolEl: HTMLDivElement | null = null;
    const makeFallback = () => {
      ok = false;
      gl?.getExtension("WEBGL_lose_context")?.loseContext();
      cv.remove();
      dash.removeAttribute("drawable");
      poolEl = document.createElement("div");
      poolEl.className = `${P}-pool`;
      poolEl.appendChild(dash);
      root.prepend(poolEl);
      setFallback(true);
    };

    // GL objects
    const progs: WebGLProgram[] = [], shaders: WebGLShader[] = [];
    let tex: WebGLTexture | null = null, vao: WebGLVertexArrayObject | null = null, vb: WebGLBuffer | null = null;
    let simT: WebGLTexture[] = [], simF: WebGLFramebuffer[] = [], cur = 0, SW = 0, SH = 0;
    let PD: WebGLProgram | null = null, PS: WebGLProgram | null = null, PF: WebGLProgram | null = null;
    const U: { [k: string]: WebGLUniformLocation | null } = {};
    let tw = 0, th = 0, hasTex = false;
    const texScale = [1, 1];
    const prog = (vs: string, fs: string) => {
      const g = gl!;
      const p = g.createProgram()!;
      for (const [t, s] of [[g.VERTEX_SHADER, vs], [g.FRAGMENT_SHADER, fs]] as [number, string][]) {
        const sh = g.createShader(t)!;
        g.shaderSource(sh, s);
        g.compileShader(sh);
        if (!g.getShaderParameter(sh, g.COMPILE_STATUS)) throw new Error(g.getShaderInfoLog(sh) || "shader");
        g.attachShader(p, sh);
        shaders.push(sh);
      }
      g.bindAttribLocation(p, 0, "aP");
      g.linkProgram(p);
      if (!g.getProgramParameter(p, g.LINK_STATUS)) throw new Error(g.getProgramInfoLog(p) || "link");
      progs.push(p);
      return p;
    };
    if (ok && gl) {
      try {
        gl.getExtension("OES_texture_float_linear");
        PD = prog(VS, DROP);
        PS = prog(VS, STEP);
        PF = prog(VS, FINAL);
        const names = [["dS", PD, "uS"], ["dD", PD, "uD"], ["dN", PD, "uN"], ["dA", PD, "uAsp"], ["sS", PS, "uS"], ["sT", PS, "uTx"],
          ["fD", PF, "uDash"], ["fS", PF, "uS"], ["fR", PF, "uRes"], ["fRc", PF, "uRect"], ["fRd", PF, "uRad"], ["fT", PF, "uT"], ["fA", PF, "uAmp"], ["fTS", PF, "uTS"], ["fX", PF, "uSTx"],
          ["uTA", PF, "uTA"], ["uTB", PF, "uTB"], ["uGr", PF, "uGr"], ["uMid", PF, "uMid"], ["uEdge", PF, "uEdge"], ["uHaze", PF, "uHaze"], ["uGlow", PF, "uGlow"], ["uK", PF, "uK"], ["uSh", PF, "uSh"], ["uLap", PF, "uLap"]] as [string, WebGLProgram, string][];
        for (const [k, p, n] of names) U[k] = gl.getUniformLocation(p, n);
        vao = gl.createVertexArray();
        gl.bindVertexArray(vao);
        vb = gl.createBuffer();
        gl.bindBuffer(gl.ARRAY_BUFFER, vb);
        gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
        gl.enableVertexAttribArray(0);
        gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
        tex = gl.createTexture();
      } catch (e) {
        console.error("UnderwaterDashboard", e);
        makeFallback();
      }
    } else makeFallback();

    // ---------------- theme: the stage colours as shader uniforms, read from the CSS variables ----------------
    const stage: { c: { [k: string]: number[] }; n: { [k: string]: number } } = { c: {}, n: {} };
    let themeKey = "";
    const probe = document.createElement("span");
    probe.className = `${P}-probe`;
    probe.setAttribute("aria-hidden", "true");
    root.appendChild(probe);
    const px = document.createElement("canvas");
    px.width = px.height = 1;
    const pctx = px.getContext("2d", { willReadFrequently: true });
    const toRGB = (css: string) => {
      if (!pctx) return [0, 0, 0];
      pctx.clearRect(0, 0, 1, 1);
      pctx.fillStyle = "#000";
      pctx.fillStyle = css;
      pctx.fillRect(0, 0, 1, 1);
      const d = pctx.getImageData(0, 0, 1, 1).data;
      return [d[0] / 255, d[1] / 255, d[2] / 255];
    };
    const readStage = () => {
      if (!ok) return;
      const cs = getComputedStyle(root);
      for (const k of STAGE_COLORS) {
        probe.style.color = `var(--${P}-${k})`;
        stage.c[k] = toRGB(getComputedStyle(probe).color);
      }
      for (const k of STAGE_NUMBERS) {
        const v = parseFloat(cs.getPropertyValue(`--${P}-${k}`));
        stage.n[k] = isFinite(v) ? v : 0;
      }
    };
    const checkTheme = () => {
      const key = props.current.theme + (root.closest(".dark") ? "|d" : "|l");
      if (key === themeKey) return false;
      themeKey = key;
      readStage();
      return true;
    };
    checkTheme();

    // ---------------- sizing ----------------
    let W = 0, H = 0, s = 1, VW = 0, VH = 0, laid = false;
    const R = { x: 60, y: 34, w: DW, h: DH };
    const makeSim = () => {
      if (!gl || !ok) return;
      simT.forEach((t) => gl.deleteTexture(t));
      simF.forEach((f) => gl.deleteFramebuffer(f));
      simT = [];
      simF = [];
      SW = Math.max(8, Math.round(VW / 2));
      SH = Math.max(8, Math.round(VH / 2));
      const cap = 640 * 1400;
      if (SW * SH > cap) {
        const k = Math.sqrt(cap / (SW * SH));
        SW = Math.round(SW * k);
        SH = Math.round(SH * k);
      }
      for (let i = 0; i < 2; i++) {
        const t = gl.createTexture()!;
        gl.bindTexture(gl.TEXTURE_2D, t);
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA16F, SW, SH, 0, gl.RGBA, gl.HALF_FLOAT, null);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
        const f = gl.createFramebuffer()!;
        gl.bindFramebuffer(gl.FRAMEBUFFER, f);
        gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, t, 0);
        gl.clearColor(0, 0, 0, 0);
        gl.clear(gl.COLOR_BUFFER_BIT);
        simT.push(t);
        simF.push(f);
      }
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      cur = 0;
    };
    const size = () => {
      W = root.offsetWidth;
      H = root.offsetHeight;
      laid = W >= 2 && H >= 2;
      if (!laid) return;
      s = Math.min(W / FW, H / FH);
      VW = W / s;
      VH = H / s;
      R.x = (VW - DW) / 2;
      R.y = Math.max(16, (VH - DH) / 2 - 24);
      if (ok) {
        let dpr = Math.min(window.devicePixelRatio || 1, 2);
        if (W * H * dpr * dpr > 4.6e6) dpr = Math.sqrt(4.6e6 / (W * H));
        cv.width = Math.max(1, Math.round(W * dpr));
        cv.height = Math.max(1, Math.round(H * dpr));
        cv.style.width = VW + "px";
        cv.style.height = VH + "px";
        cv.style.transform = `scale(${s})`;
        makeSim();
      } else if (poolEl) {
        poolEl.style.width = VW + "px";
        poolEl.style.height = VH + "px";
        poolEl.style.transform = `scale(${s})`;
        dash.style.left = R.x + "px";
        dash.style.top = R.y + "px";
      }
    };

    // ---------------- upload + render ----------------
    const upload = () => {
      if (!gl || !ok || !tex) return;
      // the element is drawn at the canvas's own pixel ratio (backing pixels per CSS px), rounded up: allocate a
      // little extra and sample only the drawn part
      const k = VW ? cv.width / VW : 1;
      const ew = dash.offsetWidth * k, eh = dash.offsetHeight * k;
      if (!ew || !eh) return;
      const w = Math.ceil(ew) + 2, h = Math.ceil(eh) + 2;
      texScale[0] = ew / w;
      texScale[1] = eh / h;
      gl.bindTexture(gl.TEXTURE_2D, tex);
      try {
        if (w !== tw || h !== th) {
          gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, w, h, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
          tw = w;
          th = h;
        }
        glx.texElementSubImage2D(gl.TEXTURE_2D, 0, 0, 0, dash);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
        hasTex = true;
      } catch (e) {
        console.error("UnderwaterDashboard upload", e);
      }
    };
    const pass = (p: WebGLProgram, uS: WebGLUniformLocation | null) => {
      const g = gl!;
      g.bindFramebuffer(g.FRAMEBUFFER, simF[1 - cur]);
      g.viewport(0, 0, SW, SH);
      g.useProgram(p);
      g.activeTexture(g.TEXTURE0);
      g.bindTexture(g.TEXTURE_2D, simT[cur]);
      g.uniform1i(uS, 0);
    };
    const drops = (ds: number[][]) => {
      const g = gl!;
      for (let k = 0; k < ds.length; k += 8) {
        const a = ds.slice(k, k + 8), f = new Float32Array(32);
        a.forEach((d, i) => {
          f[i * 4] = d[0] / VW;
          f[i * 4 + 1] = d[1] / VH;
          f[i * 4 + 2] = d[2] / VH;
          f[i * 4 + 3] = d[3];
        });
        pass(PD!, U.dS);
        g.uniform4fv(U.dD, f);
        g.uniform1i(U.dN, a.length);
        g.uniform1f(U.dA, VW / VH);
        g.drawArrays(g.TRIANGLE_STRIP, 0, 4);
        cur = 1 - cur;
      }
    };
    const step = () => {
      const g = gl!;
      pass(PS!, U.sS);
      g.uniform2f(U.sT, 1 / SW, 1 / SH);
      g.drawArrays(g.TRIANGLE_STRIP, 0, 4);
      cur = 1 - cur;
    };
    const IN: { at: ((t: number) => Ptr | null) | null; prev: Ptr | null; taps: Tap[] } = { at: null, prev: null, taps: [] };
    const simulate = (T: number, dt: number) => {
      const amp = props.current.waves;
      const n = Math.max(1, Math.min(16, Math.round(dt * 240)));
      for (let k = 1; k <= n; k++) {
        const tau = T - dt + (dt * k) / n, ds: number[][] = [];
        const ptr = IN.at ? IN.at(tau) : null;
        if (ptr && ptr.on > 0 && IN.prev) {
          const dx = ptr.x - IN.prev.x, dy = ptr.y - IN.prev.y, sp = Math.hypot(dx, dy);
          if (sp > 0.3) ds.push([ptr.x, ptr.y, 15 + ptr.on * 6, -0.042 * Math.min(1, sp / 6) * ptr.on * amp]);
        }
        IN.prev = ptr;
        while (IN.taps.length && IN.taps[0][4] <= tau) {
          const tp = IN.taps.shift()!;
          ds.push([tp[0], tp[1], tp[2], tp[3] * amp]);
        }
        if (ds.length && amp > 0) drops(ds);
        step();
      }
    };
    const v3 = (loc: WebGLUniformLocation | null, k: string) => {
      const c = stage.c[k] || [0, 0, 0];
      gl!.uniform3f(loc, c[0], c[1], c[2]);
    };
    const draw = (T: number) => {
      if (!gl || !ok || !laid || !hasTex || !simT.length) return;
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      gl.viewport(0, 0, cv.width, cv.height);
      gl.useProgram(PF);
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, tex);
      gl.uniform1i(U.fD, 0);
      gl.activeTexture(gl.TEXTURE1);
      gl.bindTexture(gl.TEXTURE_2D, simT[cur]);
      gl.uniform1i(U.fS, 1);
      gl.uniform2f(U.fR, VW, VH);
      gl.uniform4f(U.fRc, R.x, R.y, R.w, R.h);
      gl.uniform1f(U.fRd, 30);
      gl.uniform1f(U.fT, T);
      gl.uniform1f(U.fA, props.current.waves);
      gl.uniform2f(U.fTS, texScale[0], texScale[1]);
      gl.uniform2f(U.fX, 1 / SW, 1 / SH);
      v3(U.uTA, "tile-a");
      v3(U.uTB, "tile-b");
      v3(U.uGr, "grout");
      v3(U.uMid, "mid");
      v3(U.uEdge, "edge");
      v3(U.uHaze, "haze");
      v3(U.uGlow, "glow");
      gl.uniform4f(U.uK, stage.n.hazek || 0, stage.n.caus || 0, stage.n.shadow || 0, stage.n.base || 0.9);
      gl.uniform1f(U.uSh, stage.n.sheen ?? 1);
      gl.uniform1f(U.uLap, stage.n.lap ?? 1);
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
    };
    const addTap = (x: number, y: number, r: number, st: number, t: number, script: boolean) => {
      IN.taps.push([x, y, r, st, t, script]);
      IN.taps.sort((a, b) => a[4] - b[4]);
    };

    // ---------------- autoplay script (a 10.5 s timeline) and live mode ----------------
    let T = 0, mode: "auto" | "live" | "" = "", cycleStart = 0, cycleIdx = 0, added = false, typedShown = -1;
    let lastInput = -1e9, ptr: Ptr | null = null, down = false, nextRow = 0, nextRain = 0, rng = 12345;
    const rand = () => {
      rng = (rng * 1103515245 + 12345) & 0x7fffffff;
      return rng / 0x7fffffff;
    };
    const word = () => pool[cycleIdx % pool.length].city;
    // the script's positions were laid out with the dashboard at (80, 34)
    const ox = () => R.x - 80, oy = () => R.y - 34;
    const wake = (k: number) => [lerp(-40, 1240, k) + ox(), 300 + Math.sin(k * 5.2 + 0.4) * 150 - k * 40 + oy()];
    const pathAt = (t: number): Ptr & { vis: number } => {
      const sx = R.x + 910, sy = R.y + 47;
      if (t < 0.9) return { x: R.x - 120, y: R.y + 296, on: 0, vis: 0 };
      if (t < 2.7) {
        const k = sm(0.9, 2.7, t) * 0.55 + ((t - 0.9) / 1.8) * 0.45;
        const [x, y] = wake(k);
        return { x, y, on: 1, vis: 1 };
      }
      if (t < 3.25) {
        const k = sm(2.7, 3.25, t);
        const [x0, y0] = wake(1);
        return { x: lerp(x0, sx, k), y: lerp(y0, sy, k), on: 0.35, vis: 1 };
      }
      if (t < 4.55) return { x: sx + Math.sin(t * 3) * 2, y: sy, on: 0, vis: 1 };
      if (t < 6.3) {
        const k = sm(4.55, 6.3, t);
        return { x: lerp(sx, R.x + R.w - 200, k) + Math.sin(k * 9) * 70, y: lerp(sy, R.y + R.h - 30, k), on: sm(4.55, 4.8, t), vis: 1 };
      }
      if (t < 6.9) {
        const k = sm(6.3, 6.9, t);
        return { x: R.x + R.w - 200 + k * 260, y: R.y + R.h - 30 + k * 120, on: 1 - k, vis: 1 - k };
      }
      return { x: R.x + R.w + 200, y: R.y + R.h + 160, on: 0, vis: 0 };
    };
    const startCycle = (lead: number) => {
      mode = "auto";
      cycleStart = T - lead;
      added = false;
      typedShown = -1;
      IN.taps = IN.taps.filter((t) => !t[5]);
      IN.at = (tau) => pathAt(tau - cycleStart);
      IN.prev = null;
      const c0 = cycleStart;
      addTap(R.x + 790, R.y + 47, 14, -0.25, c0 + 3.25, true);
      for (const [x, y, tt] of [[300, 210, 7.0], [880, 330, 7.25], [560, 560, 7.45], [1110, 520, 7.7], [190, 470, 7.9], [740, 140, 8.15]]) addTap(x + ox(), y + oy(), 20, -0.5, c0 + tt, true);
    };
    const stopAuto = () => {
      mode = "live";
      IN.taps = IN.taps.filter((t) => !t[5]);
      IN.at = () => ptr;
      IN.prev = null;
      curEl.style.opacity = "0";
      scriptFocus = false;
      if (document.activeElement !== q && q.value) q.value = "";
      applySearch();
      nextRow = Math.max(T + 4, rowT + 5);
      nextRain = T + 9;
    };
    const runScript = (): void => {
      const ct = T - cycleStart;
      if (ct >= CYCLE) {
        cycleIdx++;
        startCycle(0);
        return runScript();
      }
      if (ct >= 4.45 && !added) {
        addRow(pool[cycleIdx % pool.length], cycleStart + 4.45);
        added = true;
      }
      const c = pathAt(ct);
      const k = Math.max(0.55, Math.min(1.3, s));
      curEl.style.opacity = String(c.vis);
      curEl.style.transform = `translate(${(c.x - 3) * s}px,${(c.y - 2) * s}px) scale(${k})`;
      const press = Math.max(0, 1 - Math.abs(ct - 3.3) / 0.25);
      ringEl.style.opacity = String(Math.min(1, c.on * 0.8 + press));
      ringEl.style.transform = `scale(${1 + press * 0.5})`;
      // typing the next order's city into the search box, then erasing it
      const w = word();
      const typed = ct < 3.45 ? 0 : Math.min(w.length, Math.floor((ct - 3.45) / 0.19) + 1);
      const erased = ct < 9.05 ? 0 : Math.min(w.length, Math.floor((ct - 9.05) / 0.1) + 1);
      const show = Math.max(0, typed - erased);
      const foc = ct >= 3.25 && ct < 9.9;
      if (show !== typedShown || foc !== scriptFocus) {
        typedShown = show;
        scriptFocus = foc;
        q.value = w.slice(0, show);
        applySearch();
      }
    };
    const runLive = () => {
      if (T > nextRow) {
        const o = { ...pool[Math.floor(rand() * pool.length)] };
        o.amount = Math.round(60 + rand() * 600) + 0.5;
        addRow(o, T);
        nextRow = T + 5 + rand() * 4;
      }
      if (T > nextRain) {
        for (let i = 0; i < 3; i++) addTap(rand() * VW, rand() * VH, 12, -0.6, T + i * 0.25, false);
        nextRain = T + 12 + rand() * 8;
      }
    };
    const tick = () => {
      const now = performance.now();
      const wantAuto = props.current.autoplay && !reduced && now - lastInput > 6000 && document.activeElement !== q;
      if (wantAuto && mode !== "auto") startCycle(mode === "" ? 0.5 : 0);
      else if (!wantAuto && mode !== "live") stopAuto();
      if (mode === "auto") runScript();
      else runLive();
      setRowK((T - rowT) / 0.6);
      setLive(T);
    };

    let raf = 0, last = 0, visible = true;
    const frame = (now: number) => {
      raf = 0;
      const dt = Math.max(0, Math.min(0.05, (now - last) / 1000));
      last = now;
      if (!laid) size();
      if (laid) {
        T += dt;
        tick();
        if (ok) {
          checkTheme();
          paint.requestPaint?.();
          if (hasTex && simT.length) {
            simulate(T, dt);
            draw(T);
          }
        }
      }
      if (visible && !document.hidden) raf = requestAnimationFrame(frame);
    };
    const start = () => {
      if (reduced || raf) return;
      last = performance.now();
      raf = requestAnimationFrame(frame);
    };
    // reduced motion: one still frame, a few frozen rings on the water; repainted only when the HTML or theme changes
    let still = false;
    const drawStill = () => {
      if (!ok || !laid || !hasTex) return;
      if (!still && simT.length) {
        still = true;
        drops([[R.x - 40, R.y + 520, 18, -0.22], [R.x + 1150, R.y + 60, 18, -0.22]]);
        for (let i = 0; i < 150; i++) step();
      }
      draw(2.4);
    };
    if (ok) {
      paint.onpaint = () => {
        upload();
        if (reduced) drawStill();
      };
    }
    const refresh = () => {
      if (!ok) return;
      if (checkTheme() && reduced) {
        paint.requestPaint?.();
        drawStill();
      }
    };
    refreshRef.current = refresh;
    let mo: MutationObserver | null = null;
    if (reduced && ok) {
      // the page's theme toggle (a `.dark` class or similar on an ancestor) repaints the still frame
      mo = new MutationObserver(refresh);
      mo.observe(document.documentElement, { attributes: true, subtree: true, attributeFilter: ["class", "data-theme", "style"] });
    }

    // ---------------- input ----------------
    const toVirtual = (e: PointerEvent) => {
      const r = root.getBoundingClientRect();
      const kx = r.width ? root.offsetWidth / r.width : 1, ky = r.height ? root.offsetHeight / r.height : 1;
      return { x: ((e.clientX - r.left) * kx) / s, y: ((e.clientY - r.top) * ky) / s };
    };
    const hit = (el: Element, x: number, y: number) => {
      // element rect in the dashboard's own layout px (works whatever is scaling it on screen)
      const dr = dash.getBoundingClientRect(), er = el.getBoundingClientRect();
      const k = dr.width ? dash.offsetWidth / dr.width : 1;
      const lx = x - R.x, ly = y - R.y;
      return lx >= (er.left - dr.left) * k && lx <= (er.right - dr.left) * k && ly >= (er.top - dr.top) * k && ly <= (er.bottom - dr.top) * k;
    };
    const onMove = (e: PointerEvent) => {
      lastInput = performance.now();
      const v = toVirtual(e);
      ptr = { x: v.x, y: v.y, on: down ? 1 : 0.55 };
      if (reduced) return;
      start();
    };
    const onDown = (e: PointerEvent) => {
      lastInput = performance.now();
      down = true;
      const v = toVirtual(e);
      ptr = { x: v.x, y: v.y, on: 1 };
      if (mode === "auto") tick();
      addTap(v.x, v.y, 16, -0.45, T, false);
      if (hit(sbox, v.x, v.y)) {
        e.preventDefault();
        setTimeout(() => {
          q.focus({ preventScroll: true });
          applySearch();
        }, 0);
      } else {
        for (const t of tabEls)
          if (hit(t, v.x, v.y)) {
            tabEls.forEach((x) => x.classList.toggle(`${P}-on`, x === t));
            paint.requestPaint?.();
          }
        if (document.activeElement === q) q.blur();
      }
    };
    const onUp = () => {
      down = false;
      if (ptr) ptr.on = 0.55;
    };
    const onLeave = () => {
      down = false;
      ptr = null;
    };
    const onRootKey = () => {
      lastInput = performance.now();
    };
    root.addEventListener("pointermove", onMove);
    root.addEventListener("pointerdown", onDown);
    root.addEventListener("pointerup", onUp);
    root.addEventListener("pointercancel", onLeave);
    root.addEventListener("pointerleave", onLeave);
    root.addEventListener("keydown", onRootKey);
    const onInput = () => {
      if (reduced) paint.requestPaint?.();
    };
    q.addEventListener("input", onInput);

    const ro = new ResizeObserver(() => {
      size();
      still = false;
      if (reduced) {
        paint.requestPaint?.();
        drawStill();
      }
    });
    const io = new IntersectionObserver(([en]) => {
      visible = en.isIntersecting;
      if (visible) start();
    });
    const onVis = () => {
      if (!document.hidden) start();
    };
    size();
    ro.observe(root);
    io.observe(root);
    document.addEventListener("visibilitychange", onVis);
    document.fonts?.ready
      .then(() => {
        if (ok) paint.requestPaint?.();
      })
      .catch(() => {});
    if (reduced) {
      if (ok) paint.requestPaint?.();
    } else start();

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      io.disconnect();
      mo?.disconnect();
      if (refreshRef.current === refresh) refreshRef.current = null;
      document.removeEventListener("visibilitychange", onVis);
      root.removeEventListener("pointermove", onMove);
      root.removeEventListener("pointerdown", onDown);
      root.removeEventListener("pointerup", onUp);
      root.removeEventListener("pointercancel", onLeave);
      root.removeEventListener("pointerleave", onLeave);
      root.removeEventListener("keydown", onRootKey);
      q.removeEventListener("input", applySearch);
      q.removeEventListener("focus", applySearch);
      q.removeEventListener("blur", applySearch);
      q.removeEventListener("keydown", onKey);
      q.removeEventListener("input", onInput);
      paint.onpaint = null;
      if (gl && ok) {
        simT.forEach((t) => gl.deleteTexture(t));
        simF.forEach((f) => gl.deleteFramebuffer(f));
        if (tex) gl.deleteTexture(tex);
        if (vb) gl.deleteBuffer(vb);
        if (vao) gl.deleteVertexArray(vao);
        progs.forEach((p) => gl.deleteProgram(p));
        shaders.forEach((sh) => gl.deleteShader(sh));
        gl.getExtension("WEBGL_lose_context")?.loseContext();
      }
      cv.remove();
      poolEl?.remove();
      probe.remove();
      dash.remove();
      if (dashRef.current === dash) dashRef.current = null;
      curEl.style.opacity = "0";
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [contentKey]);

  return (
    <div
      ref={rootRef}
      className={`${P}-root${className ? " " + className : ""}`}
      data-uwd-theme={theme === "auto" ? undefined : theme}
      role="group"
      aria-label={label || `${brand} sales dashboard seen through rippling pool water`}
      style={{
        position: "relative",
        width: "100%",
        height: "100%",
        overflow: "hidden",
        isolation: "isolate",
        background: `var(--${P}-bg)`,
        touchAction: "pan-y",
        cursor: "default",
        ...style,
      }}
    >
      <style>{CSS}</style>
      <div className={`${P}-rim`} aria-hidden="true" />
      <div ref={curRef} className={`${P}-cur`} aria-hidden="true">
        <i />
        <svg width="30" height="30" viewBox="0 0 30 30">
          <path d="M3 2 L3 24 L9 18.5 L13 27.5 L17 25.8 L13 17 L21 17 Z" fill="#fff" stroke="#0b1a33" strokeWidth="1.8" strokeLinejoin="round" />
        </svg>
      </div>
      {fallback ? (
        <div className={`${P}-tag ${P}-warn`}>
          <i />
          <b>{fallbackLabel}</b>
        </div>
      ) : badge ? (
        <div className={`${P}-tag`}>
          <i />
          <b>{badgeLabel}</b>
          {badgeDetail ? <span>{badgeDetail}</span> : null}
        </div>
      ) : null}
    </div>
  );
}

